// ans[i]: a[i]보다 오른쪽에 있는 첫 번째 더 큰 값 (없으면 -1)
stack<int> st;                    // 아직 답을 못 찾은 첨자
for (int i = 0; i < n; i++) {
    while (!st.empty() && a[st.top()] < a[i]) {
        ans[st.top()] = a[i];
        st.pop();
    }
    st.push(i);
}
while (!st.empty()) { ans[st.top()] = -1; st.pop(); }

